83: function violatesCardinality(counts: Readonly<Record<LineageRelationType, number>>): boolean {
84:   return RELATIONS.some((relation) => {
85:     const count = counts[relation];
86:     if (count === 0) {
87:       return false;
88:     }
89:     const rule = CARDINALITY[relation];
90:     return count < rule.min || count > rule.max;
91:   });
