209: /** Deduplicated adjacency for cycle detection only; `edges` keeps duplicates. */
210: function buildAdjacency(
211:   nodes: readonly IdentityVersionID[],
212:   edges: readonly LineageEdge[],
213: ): Map<IdentityVersionID, IdentityVersionID[]> {
214:   const adjacency = new Map<IdentityVersionID, Set<IdentityVersionID>>();
215:   for (const node of nodes) {
216:     adjacency.set(node, new Set<IdentityVersionID>());
217:   }
218:   for (const edge of edges) {
219:     adjacency.get(edge.child)?.add(edge.parent);
220:   }
221: 
222:   const sorted = new Map<IdentityVersionID, IdentityVersionID[]>();
223:   for (const [node, parents] of adjacency) {
224:     sorted.set(node, [...parents].sort(compareStrings));
225:   }
226:   return sorted;
