328: function isCyclicComponent(
329:   component: readonly IdentityVersionID[],
330:   adjacency: ReadonlyMap<IdentityVersionID, readonly IdentityVersionID[]>,
331: ): boolean {
332:   if (component.length > 1) {
333:     return true;
334:   }
335:   const node = component[0];
336:   return (adjacency.get(node) ?? []).includes(node);
337: }
