339: /**
340:  * Builds an immutable lineage graph snapshot from a Registry.
341:  *
342:  * Declared edges are preserved exactly, including duplicates and references to
343:  * parents that are not registered yet. Unresolved parents are grouped by child
344:  * and deduplicated for diagnostics only. Cycles are reported as sorted strongly
345:  * connected components (a self-loop is a one-node component); they do not
346:  * remove nodes or edges. `CYCLE_DETECTED` belongs to the assessment boundary of
347:  * a later traversal task and is not emitted here.
348:  */
349: export function buildLineageGraph(registry: Registry): LineageGraph {
350:   const versions = registry.versions();
351:   const nodes = [...new Set(versions.map((version) => version.id))].sort(compareStrings);
352:   const nodeSet = new Set(nodes);
353:   const edges = collectEdges(versions);
354:   const unresolvedParents = collectUnresolvedParents(nodeSet, edges);
355:   const adjacency = buildAdjacency(nodes, edges);
356:   const cycles = stronglyConnectedComponents(nodes, adjacency).filter((component) =>
357:     isCyclicComponent(component, adjacency),
358:   );
359: 
360:   const graph = deepFreeze({ nodes, edges, unresolvedParents, cycles }) as LineageGraph;
361:   BUILT_GRAPHS.add(graph);
362:   return graph;
363: }

