929:   | {
930:       readonly branch: EdgeRef;
931:       readonly reason: 'ASSURANCE_UNSATISFIED';
932:       readonly missing: readonly string[];
933:       readonly disallowed: readonly string[];
934:     }
935:   | { readonly branch: EdgeRef; readonly reason: 'CONTESTED'; readonly contestedClaims: readonly string[] };
936: 
937: type MergeClosureResult =
938:   | { readonly status: 'SATISFIED' }
939:   | {
940:       readonly status: 'UNSATISFIED';
941:       readonly code: 'ERR_MERGE_BRANCH_UNSATISFIED';
942:       readonly failures: readonly MergeClosureBranchFailure[];
943:     };
